def remove_game_data(apps, schema_editor):
    from django.db.models import Q
    from django.contrib.sessions.backends.db import SessionStore

    db = schema_editor.connection.alias
    Claim = apps.get_model('EcommerceApp', 'OnlineGiftClaim')
    Campaign = apps.get_model('EcommerceApp', 'OnlineGiftCampaign')
    Coupon = apps.get_model('EcommerceApp', 'Coupon')
    Prize = apps.get_model('EcommerceApp', 'ScratchPrize')
    Session = apps.get_model('sessions', 'Session')
    campaign_ids = set(Prize.objects.using(db).values_list('campaign_id', flat=True))
    campaign_ids.update(Campaign.objects.using(db).filter(naziv__icontains='greb').values_list('pk', flat=True))
    claims = Claim.objects.using(db).filter(Q(campaign_id__in=campaign_ids) | Q(scratch_tracking_enabled=True) | Q(scratch_trigger_order__isnull=False))
    claim_ids = set(claims.values_list('pk', flat=True))
    Coupon.objects.using(db).filter(Q(scratch_claim_id__in=claim_ids) | Q(scratch_claim__isnull=False) | Q(kod__istartswith='GREB-')).delete()
    claims.delete()
    Campaign.objects.using(db).filter(pk__in=campaign_ids).delete()
    # Clear saved rewards without signing customers out or changing their carts.
    codec = SessionStore()
    for session in Session.objects.using(db).iterator(chunk_size=500):
        data = codec.decode(session.session_data)
        reward = data.get('online_gift_reward')
        changed = False
        if isinstance(reward, dict) and (reward.get('scratch_kind') or reward.get('claim_id') in claim_ids):
            data.pop('online_gift_reward', None)
            changed = True
        for key in list(data):
            if 'greb' in key.lower():
                data.pop(key)
                changed = True
        if changed:
            Session.objects.using(db).filter(pk=session.pk).update(session_data=codec.encode(data))


def prepare_history_triggers(apps, schema_editor):
    import hashlib
    connection = schema_editor.connection
    if connection.vendor != 'sqlite':
        return
    with connection.cursor() as cursor:
        for model in ('OnlineGiftClaim', 'Coupon', 'SiteSettings', 'ScratchPrize'):
            table = apps.get_model('EcommerceApp', model)._meta.db_table
            digest = hashlib.sha256(table.encode()).hexdigest()[:16]
            for operation in ('insert', 'update', 'delete'):
                cursor.execute('DROP TRIGGER IF EXISTS ' + connection.ops.quote_name('retain_' + digest + '_' + operation))


def restore_history_triggers(apps, schema_editor):
    if schema_editor.connection.vendor == 'sqlite':
        from EcommerceApp.retention_triggers import install_history
        tables = [apps.get_model('EcommerceApp', model)._meta.db_table for model in ('OnlineGiftClaim', 'Coupon', 'SiteSettings')]
        install_history(schema_editor.connection, tables=tables)


